/bin/bash -lc "apply_patch <<'PATCH'
*** Begin Patch
*** Update File: Task.v
@@
-  intros K T H; induction H; intros k U Hle; simpl;
+  intros K T H; induction H; intros depth U Hle; simpl;
     try (f_equal; eauto; fail); auto.
   rewrite Nat.eqb_neq by lia. reflexivity.
@@
-  intros K j t H; induction H; intros k u Hle; simpl;
+  intros K j t H; induction H; intros depth u Hle; simpl;
     try (f_equal; eauto; fail); auto.
   rewrite Nat.eqb_neq by lia. reflexivity.
@@
-  intros K j t H; induction H; intros k U Hle; simpl;
+  intros K j t H; induction H; intros depth U Hle; simpl;
*** End Patch
PATCH
( sed '/"'^Theorem polymorphic_identity_theorem_for_free/,$d'"' Task.v; echo 'End SystemFParametricityIfHardTask.' ) > /tmp/TaskPrefix.v
coqc /tmp/TaskPrefix.v"

